     2832:             *value = (float *)origdata;
     2833:             return (TIFFReadDirEntryErrOk);
     2834:         default:
     2835:             break;
     2836:     }
>>>  2837:     data = (float *)_TIFFmallocExt(tif, count * sizeof(float));
